#include <vector>
#include <cstring>
#include <cstdio>

int main() {
    std::vector<char> v;
    // Must reserve space for string + null terminator
    v.resize(41); 

    // Safe C API usage using &v[0]
    // &v[0] provides the T* pointer to the contiguous memory
    strcpy(&v[0], "hello, world"); 

    // Output using C function
    printf("%s\n", &v[0]);

    // C++11 standard equivalent (preferred)
    std::vector<int> data = {1, 2, 3};
